import { esc } from '../ui.js';
export function weekDates(offset){return Array.from({length:7},(_,i)=>new Date(Date.UTC(2026,8,20+offset*7+i)).toISOString().slice(0,10));}
export default function calendar({state,ui}){const dates=weekDates(ui.week);return `<div class="calendar-top"><span class="user-dot">●</span> צוות הדגמה <button class="outline small" data-action="new-event">＋ פגישה חדשה</button></div><section class="calendar-shell"><div class="calendar-toolbar"><span class="calendar-view">שבוע</span><strong>${dates[0]} — ${dates[6]}</strong><div class="actions"><button class="outline" data-action="week-today">היום</button><button class="outline" data-action="week-prev" aria-label="שבוע קודם">◀</button><button class="outline" data-action="week-next" aria-label="שבוע הבא">▶</button></div></div><div class="calendar-scroll"><div class="week"><aside class="time-ruler"><span></span>${Array.from({length:13},(_,i)=>`<small>${String(i+8).padStart(2,'0')}:00</small>`).join('')}</aside>${dates.map((date,i)=>`<section class="day ${i===0?'today':''}"><h3>${['א׳','ב׳','ג׳','ד׳','ה׳','ו׳','ש׳'][i]}, ${date.slice(8)}.${date.slice(5,7)}</h3><div class="day-hours">${state.events.filter(e=>e.date===date).map(e=>{const [h,m]=e.time.split(':').map(Number);return `<button class="event" style="top:${Math.max(0,Math.min(12,h-8+m/60))*44}px" data-action="edit-event" data-id="${e.id}"><b>${esc(e.time)}</b> ${esc(e.title)}</button>`;}).join('')}</div></section>`).join('')}</div></div></section>`;}
